(function(){
var bank=document.getElementById('fz-bank');
if(bank){
  var floorEl=document.getElementById('fz-floor'),ver=document.getElementById('fz-ver'),
      verOut=document.getElementById('fz-verout'),flash=document.getElementById('fz-flash'),
      undo=document.getElementById('fz-undo'),log=document.getElementById('fz-log'),N=12,floor=3;
  function draw(){
    while(bank.firstChild)bank.removeChild(bank.firstChild);
    for(var i=0;i<N;i++){
      var c=document.createElement('span');
      c.className='fz-cell'+(i<floor?' on':'');
      c.textContent=i<floor?'1':'0';
      bank.appendChild(c);
    }
    floorEl.textContent=floor;
  }
  function say(t,k){log.textContent=t;log.className='fz-log'+(k?' '+k:'');}
  ver.addEventListener('input',function(){verOut.textContent=ver.value;});
  flash.addEventListener('click',function(){
    var v=+ver.value;
    if(v<floor){say('boot rejected. image version '+v+' is below the anti-rollback floor of '+floor+'.','bad');return;}
    var was=floor;floor=v;draw();
    if(was===v){say('booted. version '+v+' matches the floor, so no new fuse was blown.','ok');}
    else{var d=v-was;say('booted. '+d+' more fuse'+(d===1?'':'s')+' blown. the floor is now '+v+'.','ok');}
  });
  undo.addEventListener('click',function(){
    say('there is no such operation. blowing a fuse adds a one, and nothing in the instruction set turns a one back into a zero.','bad');
  });
  draw();
}
var imgs=document.getElementById('fz-imgs');
if(imgs){
  var sig=document.getElementById('fz-sig'),rb=document.getElementById('fz-rb'),FLOOR=6,
      IMG={cur:{v:7,ok:true},old:{v:4,ok:true},mod:{v:7,ok:false}};
  function set(el,txt,k){el.textContent=txt;el.className='fz-verdict '+k;}
  imgs.addEventListener('click',function(e){
    var b=e.target.closest?e.target.closest('button[data-k]'):null;
    if(!b)return;
    var m=IMG[b.getAttribute('data-k')];if(!m)return;
    var all=imgs.querySelectorAll('button[data-k]');
    for(var i=0;i<all.length;i++)all[i].classList.toggle('sel',all[i]===b);
    if(!m.ok){
      set(sig,'rejected. the signature does not verify.','bad');
      set(rb,'rejected. the signature does not verify.','bad');
    }else if(m.v<FLOOR){
      set(sig,'accepted. signed by the vendor, so it boots.','ok');
      set(rb,'rejected. version '+m.v+' is below the floor of '+FLOOR+'.','bad');
    }else{
      set(sig,'accepted. signed by the vendor, so it boots.','ok');
      set(rb,'accepted. signed, and version '+m.v+' is at or above the floor of '+FLOOR+'.','ok');
    }
  });
}
})();
